#!/bin/bash
set -e

echo "[1/6] Building il CLI..."
cd /workspace
cargo build --release --bin il 2>&1 | tail -5

echo "[2/6] Initializing repository..."
cd /work
git init --initial-branch=main repo >/dev/null 2>&1
cd repo

cat > repository_state.json << 'EOF'
{
  "project_id": "il",
  "schema_version": "1.0.0",
  "head_revision": 0,
  "last_verified_revision": 0,
  "compiler_version": null,
  "runtime_version": null,
  "target": "x86_64-unknown-linux-gnu",
  "open_tasks": ["P02"],
  "blocked_tasks": [],
  "failed_tasks": [],
  "locks": {}
}
EOF

mkdir -p examples/bootstrap
cat > examples/bootstrap/graph.json << 'EOF'
{
  "project_id": "il",
  "graph_version": "1.0.0",
  "revision": 0,
  "target": "x86_64-unknown-linux-gnu",
  "modules": [],
  "types": [],
  "functions": [],
  "capabilities": [],
  "packages": [],
  "contracts": []
}
EOF

cat > toolchain.lock << 'EOF'
{
  "target": "x86_64-unknown-linux-gnu",
  "rust": "1.90.0",
  "llvm": "14.0.6"
}
EOF

git add . >/dev/null 2>&1
git -c user.name=B -c user.email=b@l -c commit.gpgsign=false commit -m init >/dev/null 2>&1

mkdir -p .git/il
COMMIT=$(git rev-parse HEAD)
TREE=$(git rev-parse HEAD^{tree})

cat > .git/il/revision_bindings.json << EOF
{
  "schema_version": "1.0.0",
  "bindings": [{
    "revision": 0,
    "git_commit": "$COMMIT",
    "tree_hash": "$TREE"
  }]
}
EOF

echo "[3/6] Publishing source..."
cat > /work/transact.json << 'JSONEOF'
{
  "task_id": "P02",
  "base_revision": 0,
  "scope": ["program"],
